const crypto = require('crypto');

const authorization = $json.headers?.authorization ?? $json.headers?.Authorization ?? '';
if (!authorization.startsWith('Bearer ')) {
  return [{ json: { authorized: false, statusCode: 401, error: 'Sesión requerida.' } }];
}

const secret = $env.JWT_SECRET;
if (!secret) {
  return [{ json: { authorized: false, statusCode: 500, error: 'JWT_SECRET no está configurado en n8n.' } }];
}

try {
  const token = authorization.slice(7).trim();
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Formato inválido');

  const [encodedHeader, encodedPayload, signature] = parts;
  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${encodedHeader}.${encodedPayload}`)
    .digest('base64url');

  const receivedBuffer = Buffer.from(signature);
  const expectedBuffer = Buffer.from(expected);
  if (receivedBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(receivedBuffer, expectedBuffer)) {
    throw new Error('Firma inválida');
  }

  const payload = JSON.parse(Buffer.from(encodedPayload, 'base64url').toString('utf8'));
  if (payload.exp && payload.exp <= Math.floor(Date.now() / 1000)) throw new Error('Token vencido');

  const role = String(payload.rol ?? payload.role ?? payload.codigoRol ?? '').toUpperCase();
  const permissions = Array.isArray(payload.permisos) ? payload.permisos : [];
  const canManageParking = role === 'ADMINISTRADOR_PARKING' || permissions.includes('PARQUEADERO_GESTIONAR');
  if (!canManageParking) {
    return [{ json: { authorized: false, statusCode: 403, error: 'No tiene permisos para administrar parqueadero.' } }];
  }

  return [{ json: { authorized: true, panelUserId: Number(payload.uid ?? payload.sub ?? 0), role } }];
} catch (error) {
  return [{ json: { authorized: false, statusCode: 401, error: 'La sesión es inválida o ha vencido.' } }];
}
